// Bit-exact parity test for the FULL single GDN layer decode step.
// Compares C++ gdn_layer_forward against vectors generated by the REAL
// Qwen4ExpGatedDeltaNet.__call__ (tools/gen_gdn_layer_vectors.py), viewing the
// float results as raw uint32 bits — byte-for-byte, not by tolerance.
#include "../src/gdn_layer.hpp"

#include <mlx/mlx.h>

#include <cstdint>
#include <cstdio>
#include <string>

namespace mx = mlx::core;
using namespace veystrix::engine;

// True bit reinterpretation (astype float->uint32 would CONVERT numerically).
static bool bit_equal(const mx::array& a, const mx::array& b) {
  if (a.shape() != b.shape() || a.dtype() != b.dtype()) return false;
  mx::array av = mx::view(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::view(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  if (av.size() != bv.size()) return false;
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i)
    if (pa[i] != pb[i]) return false;
  return true;
}

static void dump_first_diff(const char* label, const mx::array& a,
                            const mx::array& b) {
  mx::array av = mx::view(mx::reshape(a, {-1}), mx::uint32);
  mx::array bv = mx::view(mx::reshape(b, {-1}), mx::uint32);
  mx::eval(av, bv);
  const uint32_t* pa = av.data<uint32_t>();
  const uint32_t* pb = bv.data<uint32_t>();
  for (size_t i = 0; i < av.size(); ++i) {
    if (pa[i] != pb[i]) {
      std::fprintf(stderr, "  %s first diff at %zu: got 0x%08x expected 0x%08x\n",
                   label, i, pa[i], pb[i]);
      return;
    }
  }
}

int main(int argc, char** argv) {
  if (argc < 2) {
    std::fprintf(stderr, "usage: %s <vectordir>\n", argv[0]);
    return 2;
  }
  const std::string dir = argv[1];
  auto load = [&](const char* n) { return mx::load(dir + "/" + n + ".npy"); };

  mx::array x = load("x");
  mx::array w_qkv = load("w_qkv"), w_z = load("w_z");
  mx::array w_b = load("w_b"), w_a = load("w_a");
  mx::array conv_w = load("conv_w"), A_log = load("A_log");
  mx::array dt_bias = load("dt_bias"), norm_w = load("norm_w");
  mx::array w_out = load("w_out");
  mx::array conv_state = load("conv_state"), rec_state = load("rec_state");
  mx::array exp_out = load("expected_output");
  mx::array exp_conv = load("expected_conv_state");
  mx::array exp_rec = load("expected_rec_state");

  GDNWeights weights(w_qkv, w_z, w_b, w_a, conv_w, A_log, dt_bias,
                     norm_w, w_out);
  GDNCacheState cache(conv_state, rec_state);

  // Derive geometry from the saved shapes so the test tracks the generator.
  const int H = x.shape(2);
  const int conv_dim = w_qkv.shape(0);
  const int value_dim = w_z.shape(0);
  const int key_dim = (conv_dim - value_dim) / 2;
  const int Hv = A_log.shape(0);
  const int Dk = rec_state.shape(3);
  const int Dv = rec_state.shape(2);
  const int Hk = key_dim / Dk;
  const int K = conv_state.shape(1) + 1;
  GDNConfig cfg{H, key_dim, value_dim, Hk, Hv, Dk, Dv, K,
                1e-6f, GDNActivation::Sigmoid};

  GDNLayerOutput got = gdn_layer_forward(x, weights, cache, cfg);
  mx::eval(got.output, got.conv_state, got.recurrent_state);

  bool ok = true;
  if (!bit_equal(got.output, exp_out)) {
    std::fprintf(stderr, "FAIL: layer output differs\n");
    dump_first_diff("output", got.output, exp_out);
    ok = false;
  }
  if (!bit_equal(got.conv_state, exp_conv)) {
    std::fprintf(stderr, "FAIL: new conv_state differs\n");
    dump_first_diff("conv_state", got.conv_state, exp_conv);
    ok = false;
  }
  if (!bit_equal(got.recurrent_state, exp_rec)) {
    std::fprintf(stderr, "FAIL: new recurrent state differs\n");
    dump_first_diff("rec_state", got.recurrent_state, exp_rec);
    ok = false;
  }

  if (!ok) return 1;
  std::printf("test_gdn_layer OK (bit-exact)\n");
  return 0;
}
